// Project-aspect standard pack: the self-growing product research wiki
// (compile-once/refine-in-place, cited, dated, isolated behind the reviewed
// product-requirements crossing point). The folder is the classifier: the two
// reserved names (product-requirements/, sample-data/) have fixed meaning;
// everything else under product-wiki/ is wiki space. Fingerprinted by the
// standard's one structural constant — the sink.
import { SINK_README } from './lib.mjs';

export default {
  version: '60913.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'agent-maintained market, user and competitor research wikis — cited pages, growth logs, the reviewed product-requirements sink',
    excludes: 'how the product is built or specced — that is spec-driven-product; requirement proofs are executable-requirements',
  },
  marker: SINK_README,
  detect: (ctx) => ctx.tracked.includes(SINK_README),
  // The isolation wall (product-wiki-isolation) and the skeleton check
  // (product-wiki-layout) are both declared checks in this pack's
  // declared-checks.json. They are a designed pair: the barrier's glob target
  // fails closed on an empty product-wiki/ expansion, and layout owns the
  // missing-skeleton complaint. A declared check is run by the engine, so this
  // pack needs nothing else declared for its wall to stand (#1681 dropped the
  // `barriers` requirement, vestigial since the wall stopped being code).
  // Editing the wiki tree is the writing-wiki-pages skill's territory — its own
  // `force-load-on-file-edits-paths` names product-wiki/**, and the guard holds a file tool aimed
  // there until the session has loaded it — so the page rules are read once, by
  // the session that edits, rather than carried as prose by every session.
  // Adoption interview: the standard takes no config (the layout IS the config),
  // but a wiki with no research scope is a hollow skeleton — the answers frame
  // WHICH wikis get seeded and what the competitor set is measured against. They
  // record as intent on the entry (`answers`), never as config. Read the repo's
  // own product brief/spec first and confirm, rather than re-asking cold.
  questions: [
    {
      id: 'product',
      prompt: "What is the product — what does it do, and what is the core value it delivers? If the repo already carries a product brief or spec, read it and confirm rather than asking cold.",
      distill: 'recorded as intent on this entry (the pack takes no config); it names what the research is about and frames every seeded wiki',
    },
    {
      id: 'users',
      prompt: 'Who are the users or customers — the segments whose needs the research must track?',
      distill: 'recorded as intent; scopes the user-research wiki and whose problems the findings answer to',
    },
    {
      id: 'market',
      prompt: 'What market or category is this in, and who are the main competitors or alternatives? This is what the competitor research is scoped against.',
      distill: 'recorded as intent; names the competitor set the initial competitor-landscape wiki is seeded from',
    },
  ],
  // The pack's scheduled task — wiki-growth, the weekly research pass — lives in
  // this pack's `tasks/wiki-growth/`, discovered by the scheduler's filesystem
  // scan (packs/claudinite-tasks/discover.mjs), not declared here.
};

// Claudinite's own surface in a repo that runs it: the vendored mount, the
// declaration that activates a pack, adopting Claudinite and adopting a pack.
//
// EVERY RULE HERE JUDGES A MEMBER'S CLAUDINITE STATUS — is this repo declared,
// converged, gated and scheduled such that Claudinite works in it. Rules about
// how the canon's own content is maintained are not this pack's, however much
// they look like it.
//
// MANDATORY. `basics` requires this pack, which both vendors its content and
// materializes its declaration wherever a declaration is written; the
// migrations/2026-08-14-core-seed record declares it into members that already
// exist. Both run outside any check — activation reads the literal declaration,
// so `claudinite-lifecycle-declared` reports a member that has lost the entry rather
// than being what puts it there.
export default {
  version: '60911.1',
  minEngineVersion: '60822.1',
  ruleRoutingGuidance: {
    belongs: 'using Claudinite itself — the vendored mount, the pack declaration, bootstrapping, adopting packs, the self-refresh update',
    excludes: 'working discipline and the task lifecycle — basics; authoring Claudinite content, scheduled tasks included — claudinite-growth; git — git-github',
  },
  seededByDefault: true,
  // The consumer-isolation wall (claudinite-isolation) is a declared check — a
  // forbidReferences entry in this pack's declared-checks.json, run by the
  // engine's reference-scanning like any barrier, so it needs nothing else
  // declared. The per-repo config rule a member's own edges ride now lives in
  // `basics` (#1681), which this pack cannot require back without a cycle —
  // `basics` requires this one. It is seeded into every member anyway.
  // Both scheduled tasks live in this pack's `tasks/`, discovered by the
  // scheduler's filesystem scan (packs/claudinite-tasks/discover.mjs) rather than
  // declared here: `update`, the per-repo self-refresh every member runs, and
  // `adopt-requested-packs`, which acts on a repo's pack-adoption requests.
  //
  // `update` being HERE is what `claudinite-lifecycle-declared` is blocking for. A member runs it
  // from its vendored copy and discovery finds only a literally-declared pack's
  // tasks, so a repo that loses this pack's entry loses its self-refresh — and
  // nothing is left that could deliver it one.
};

import { NEEDS_HUMAN } from './engine-update.mjs';

// THE UNIFORM TERMINAL (docs/versioned-updates/DESIGN.md §3.9, §5). What happens to
// an update's PR, given what the flow returned — one function for every flow, so
// "how does an update end" has a single answer no shell can re-decide.
//
// The rule the design is emphatic about: **every non-green end looks the same**.
// An unanswered interview, an agentic repair that left checks red, a migration that
// could not complete, a pack whose engine is too old — none of them is a special
// case with its own handling. The PR stays open, the work item is labelled,
// the run stops. Interviews were one instance of that rule, never the rule.
//
// PRECEDENCE, most-specific first, and the order is the point:
//
//   1. `needs-human` — a terminal the flow already reached. Nothing downstream may
//      override it, including a repo that would otherwise auto-merge.
//   2. `apply-stage` — the pack flow's agentic tail is needed. It is NOT a merge:
//      the rules have landed but nothing has yet reconciled them with the member's
//      own content — nor run the member's own tests over what the cycle wrote
//      (../updates/converge-scope.mjs) — and merging first would call that
//      reconciliation optional.
//   3. whatever the flow's own delivery decision said — merge, or keep for review.
//
// Returning `{ action, label, why }` rather than a bare verb because the shell has
// to be able to say, in the PR and in the log, why the run ended where it did. A
// terminal nobody can explain is one nobody will trust the next time it fires.
export const TERMINALS = ['merge', 'keep', 'apply-stage', 'needs-human'];

export function terminalFor(outcome) {
  if (!outcome || typeof outcome !== 'object') {
    return { action: 'needs-human', label: NEEDS_HUMAN, why: 'the update flow returned nothing to act on' };
  }
  if (outcome.status === NEEDS_HUMAN) {
    return { action: 'needs-human', label: NEEDS_HUMAN, why: outcome.detail ?? 'the flow ended at a human terminal' };
  }
  if (outcome.applyStage?.needed) {
    return {
      action: 'apply-stage',
      packs: outcome.applyStage.packs ?? [],
      withheld: outcome.applyStage.withheld ?? [],
      why: outcome.applyStage.why ?? 'the pack\'s new rules must be applied to content the canon has never seen',
