71	// What a pack update would do to each declared pack, judged before anything is
72	// written: its installed version, the version this canon ships, whether the repo's
73	// engine satisfies the pack's minimum, and the records in between.
74	//
75	// `blocked` is the whole point of returning this rather than a boolean. A pack the
76	// engine is too old for is not skipped quietly and not applied hopefully — it is
77	// named, with both numbers, because the fix (update the engine first) is a sentence
78	// long and unguessable from a silent no-op.
79	export function planPackUpdates(packs, declared, installed, { today, engineVersion = ENGINE_VERSION } = {}) {
80	  const byId = new Map(packs.map((p) => [p.id, p]));
81	  const plan = [];
82	  for (const entry of resolveDeclaredPacks(declared ?? [], packs)) {
83	    const id = packEntryId(entry);
84	    const pack = id === undefined ? undefined : byId.get(id);
85	    if (!pack || plan.some((p) => p.id === id)) continue;      // a local pack, or already planned
86	    const from = installed?.packVersions?.[id];
87	    const to = pack.version;
88	    const needs = pack.minEngineVersion;
89	    const blocked = isVersion(needs) && versionAbove(needs, engineVersion)
90	      ? `pack "${id}" version ${to} needs engine ${needs}; this repo runs engine ${engineVersion}`
91	      : null;
92	    plan.push({
93	      id,
94	      from: isVersion(from) ? from : null,
95	      to: isVersion(to) ? to : null,
96	      blocked,
97	      records: packRecordsInGap(id, installed, { today }),
98	    });
99	  }
100	  return plan;
101	}
