103	const outcome = (status, detail, extra = {}) => ({ status, detail, ...extra });
104	
105	// Everything under here is a path this flow's caller cannot push, and the one
106	// definition of that fact. A record naming such a path is withheld from the pushed tree
107	// and staged for the apply stage, which delivers it on a credential that can.
108	export const WORKFLOW_DIR = '.github/workflows/';
109	
110	// Where a withheld workflow file waits between this run staging it and the apply stage
111	// delivering it. Inside `.claudinite/`, so it rides the ordinary push the Action token
112	// CAN make; only the real `.github/workflows/` path is refused.
113	export const PENDING_DIR = '.claudinite/pending-workflows/';
114	
115	// Where a withheld workflow path is staged. One level deep and named for the workflow
116	// file itself, so the apply stage recovers the destination from the staged name alone.
117	export const stagedAt = (workflowPath) => `${PENDING_DIR}${workflowPath.slice(WORKFLOW_DIR.length)}`;
