122	export function stagedFiles(targetRoot) {
123	  const dir = join(targetRoot, PENDING_DIR);
124	  if (!existsSync(dir)) return [];
125	  return readdirSync(dir, { withFileTypes: true }).filter((e) => e.isFile()).map((e) => `${PENDING_DIR}${e.name}`);
