140	// content any more: the files are static after adoption and the tasks pack scaffolds
141	// them there (converge-workflows.mjs). `pending: null` is what "nothing to deliver"
142	// has always meant to a caller, so a stale worker still reads a coherent answer.
143	export async function pendingSchedulerWorkflow() { return { pending: null, error: null }; }
144	export async function pendingExecutorWorkflow() { return { pending: null, error: null }; }
