146	// How many of the test-visible paths the reason NAMES before collapsing the rest to
147	// a count. The reason becomes a work item's `reason.detail`, a summary surface: a
148	// migration that rewrites a hundred sources would otherwise put a hundred paths in
149	// it, and the branch is where they are actually read.
150	const TEST_VISIBLE_NAMED = 5;
151	
152	export function applyStageFor(specs, withheld = [], testVisible = []) {
153	  const asked = specs.filter((m) => m.applyStage);
154	  if (!asked.length && !withheld.length && !testVisible.length) return { needed: false };
155	  // A withheld workflow file needs the stage on its own, with no record asking: the file
156	  // is staged and undelivered, and only the stage's credential can finish it.
157	  // The reason names the CONDITION and the ARTIFACTS BY IDENTITY, and stops there —
158	  // it becomes `reason.detail` on the work item, and the payload it rides in
159	  // carries identifiers, never instructions (./terminals.mjs). So a record that
160	  // asked for a session is named, not quoted: its `applyStage.instructions` are in
161	  // the mount the update just vendored, on the branch the session is given, and the
162	  // session reads them from there like any other fact about the repo.
163	  const why = [
164	    ...(withheld.length ? [`${withheld.length} withheld workflow file(s) staged under ${PENDING_DIR}`] : []),
165	    ...asked.map((m) => `${m.dir}: ${m.applyStage.why}`),
166	    ...(testVisible.length
167	      ? [`this converge wrote ${testVisible.length} file(s) the repo's own tests can see (${testVisible.slice(0, TEST_VISIBLE_NAMED).join(', ')}${testVisible.length > TEST_VISIBLE_NAMED ? `, +${testVisible.length - TEST_VISIBLE_NAMED} more` : ''})`]
168	      : []),
169	  ].join('; ');
170	  return {
171	    needed: true,
172	    // The packs that RAISED the records, not every pack whose version moved: this
173	    // scopes a session, and naming packs with nothing to apply widens it.
174	    packs: [...new Set(asked.map((m) => flowOf(m.dir).pack))],
175	    records: asked.map((m) => m.dir),
176	    withheld,
177	    why,
178	  };
179	}
180	
181	// Update `targetRoot`'s declared packs to the versions this canon ships. Same
182	// arguments and same terminals as the engine flow; `dryRun` judges everything and
183	// writes nothing.
184	export async function packUpdate(targetRoot, {
185	  fullName, today, dryRun = false, delivery = 'auto-merge', forceMergeOnRedCi = false, selfTestRun,
186	  extraRecords = [],
187	} = {}) {
188	  const settingsFile = settingsPath(targetRoot);
189	  if (!existsSync(settingsFile)) {
190	    return outcome(NEEDS_HUMAN, `${targetRoot} has no ${DECLARATION_FILE} — it has never adopted Claudinite`);
191	  }
192	  let raw;
193	  try { raw = JSON.parse(readFileSync(settingsFile, 'utf8')); }
194	  catch (e) { return outcome(NEEDS_HUMAN, `${DECLARATION_FILE} is not valid JSON: ${e.message}`); }
195	
196	  // The shape reader canonicalizes a legacy map's keys on the way out: a pack
197	  // renamed since a member last stamped it reads as never-installed otherwise.
198	  const installed = hasInstalledMount(raw) ? installedVersions(raw) : null;
199	  const declared = Array.isArray(raw.packs) ? raw.packs : [];
200	  const packs = await loadPacks();
201	
202	  // The engine the TARGET runs, not the one this canon ships: a member is updated
203	  // engine-first, and a pack update that read the canon's number would enforce
204	  // `minEngineVersion` against an engine the repo does not have.
205	  const engineVersion = isVersion(installed?.engineVersion) ? installed.engineVersion : ENGINE_VERSION;
206	  const plan = planPackUpdates(packs, declared, installed, { today, engineVersion });
207	
208	  const blocked = plan.filter((p) => p.blocked);
209	  if (blocked.length) {
210	    return outcome(NEEDS_HUMAN, blocked.map((p) => p.blocked).join('; '), { plan });
211	  }
212	
213	  const { files, errors } = await computeVendorSet(declared, { today, installed });
214	  if (errors.length) return outcome(NEEDS_HUMAN, errors.map((e) => e.what).join('; '), { errors, plan });
215	
216	  const ids = plan.map((p) => p.id);
217	  const packFiles = files.filter((f) => ids.some((id) => isPackFile(f, id)));
218	  if (dryRun) {
219	    return outcome('ok', `would update ${plan.length} pack(s)`, { plan, files: packFiles.length, dryRun: true });
220	  }
221	
222	  // 1. Replace each declared pack's tree wholesale — per pack, so a pack that is no
223	  //    longer declared keeps its files until the flow that owns removal takes them,
224	  //    and a pack this run does not touch is never disturbed. A pack the canon has
225	  //    RENAMED takes its old directories with it (legacySpellingsOf above).
226	  const sharedDir = join(targetRoot, SHARED_SUBDIR);
227	  for (const id of ids) {
228	    rmSync(join(sharedDir, 'packs', id), { recursive: true, force: true });
229	    for (const legacy of legacySpellingsOf(id)) rmSync(join(sharedDir, 'packs', legacy), { recursive: true, force: true });
230	  }
231	  for (const file of packFiles) {
232	    const dest = join(sharedDir, file);
233	    mkdirSync(dirname(dest), { recursive: true });
234	    copyFileSync(join(canonRoot, file), dest);
235	  }
236	
237	  // 2. Run each pack's records, in the order the gap gives them.
238	  const wanted = new Set(plan.flatMap((p) => p.records));
239	  const specs = (await loadMigrations()).filter((m) => wanted.has(m.dir));
240	  const exists = (p) => existsSync(join(targetRoot, p));
241	  const read = (p) => (existsSync(join(targetRoot, p)) ? readFileSync(join(targetRoot, p), 'utf8') : null);
242	
243	  const put = (p, c) => { mkdirSync(dirname(join(targetRoot, p)), { recursive: true }); writeFileSync(join(targetRoot, p), c); };
244	
245	  // A path under `.github/workflows/` is WITHHELD from the pushed tree and staged for the
246	  // apply stage (#649, re-opened in #1509). The flow's caller pushes with the Action's
247	  // GITHUB_TOKEN, which GitHub never lets write there, and the refusal rejects the whole
248	  // ref — so the file must not be in the tree this run commits. The apply stage is a
249	  // different credential: it raises a work item for an agent session, and the Claude
250	  // GitHub App carries `workflows: write`, which is what actually delivers the file.
251	  //
252	  // #1317 dropped these writes instead, on the ground that "a member's workflows are
253	  // static after adoption". #1494 is the counterexample — the executor's CLAUDINITE_VARS
254	  // line is a workflow change every member needs — so the lane is open again.
255	  const withheld = [];
256	  // Which packs finished this run still OWING a file. A withheld path is delivered by
257	  // the apply stage on another credential, not here, so the pack it belongs to has not
258	  // actually reached the version this run would stamp — see the stamp step below.
259	  //
260	  // Attributed as the write happens rather than by counting `withheld` afterwards: two
261	  // records from DIFFERENT packs may name the same workflow path, and the second one's
262	  // write grows nothing, so a count would stamp the pack whose content is the one
263	  // actually staged.
264	  const owesDelivery = new Set();
265	  let owedBy = null;
266	  const write = (p, c) => {
267	    if (!p.startsWith(WORKFLOW_DIR)) return put(p, c);
268	    put(stagedAt(p), c);
269	    if (!withheld.includes(p)) withheld.push(p);
270	    if (owedBy) owesDelivery.add(owedBy);
271	  };
272	  const move = (from, to) => { mkdirSync(dirname(join(targetRoot, to)), { recursive: true }); renameSync(join(targetRoot, from), join(targetRoot, to)); };
273	  const readTemplate = (p) => (existsSync(join(canonRoot, p)) ? readFileSync(join(canonRoot, p), 'utf8') : null);
274	  // The announcement is what un-skips a record naming a workflow path. It is an env
275	  // handshake rather than a probe of the disk because what matters is what THIS process
276	  // can do, and the vendor step earlier in this same cycle already replaced the on-disk
277	  // worker while the old code is still running (registry.mjs states the same).
278	  // Beyond the classic set, for the scheduling-fields codemod (the registry says
279	  // why it is inert without it).
280	  const listDir = (p) => { try { return readdirSync(join(targetRoot, p)); } catch { return null; } };
281	  const io = { exists, move, read, write, readTemplate, listDir, env: { [WITHHOLD_CAPABLE_ENV]: '1' } };
282	  const applied = [];
283	  for (const m of [...specs, ...extraRecords]) {
284	    owedBy = flowOf(m.dir).pack ?? null;
285	    applied.push(...(await applyMigration(m, io)));
286	  }
287	  owedBy = null;
288	
289	  // 2c. THE CLAUDE.md PACK INDEX (#807), for the same reason as 2b and at the same
290	  //     point: its content is a function of the pack set, and the vendor above is
291	  //     what just changed it. The engine flow converges the index too, but it runs
292	  //     BEFORE the packs in a cycle — so on the one night a pack lands, the engine
293	  //     flow's copy is already yesterday's, and without this the member would carry
294	  //     a stale index (and inject the whole corpus through the hook as a fallback)
295	  //     until some later cycle happened to touch the engine.
296	  //
297	  //     Written straight to the tree rather than withheld: the index is not a
298	  //     workflow path, so no credential refuses it.
299	  const { writeRulesIndex, RULES_INDEX_FILE } = await import('../../../engine/pack_loader/generate-rules-index.mjs');
300	  const { ensureRulesIndexImport, ensureRulesIndexMergeAttribute } = await import('../../../engine/converge-wiring.mjs');
301	  if (await writeRulesIndex(targetRoot)) applied.push(`converged ${RULES_INDEX_FILE}`);
302	  if (ensureRulesIndexImport(targetRoot)) applied.push('added the CLAUDE.md pack-index import');
303	  if (ensureRulesIndexMergeAttribute(targetRoot)) applied.push('declared merge=ours for the pack index');
304	
305	  // …and sweep the staging directory of anything this run did NOT put there: a file
306	  // staged by an earlier cycle was either delivered or abandoned, and either way the
307	  // record that staged it would stage it again. Scoping the sweep is load-bearing — an
308	  // unscoped one deletes the delivery this very run just staged, silently and green.
309	  const stagedNow = new Set(withheld.map(stagedAt));
310	  for (const stale of stagedFiles(targetRoot)) {
311	    if (stagedNow.has(stale)) continue; // this run's own delivery, not a leftover
312	    rmSync(join(targetRoot, stale), { force: true });
313	  }
314	
315	  // 3. Stamp each updated pack's version. Written per pack rather than wholesale, so
316	  //    a pack this run did not touch keeps the number it really has.
317	  const next = JSON.parse(readFileSync(settingsFile, 'utf8'));
318	  // Only what this run moved: a version lands on the entry of the pack it prices,
319	  // and a pack this run did not touch keeps the number it really has. The old
320	  // spelling of a renamed pack cannot be carried forward here even by accident —
321	  // there is no map to carry it in, only entries the declaration itself names
322	  // (#1041 is what a second key in a central map cost).
323	  //
324	  //    A PACK THAT STILL OWES A WITHHELD FILE IS NOT STAMPED (#1545). The stamp is
325	  //    this member's claim to have received the version, and a version whose record
326	  //    staged a workflow file has been received only once the apply stage delivers it.
327	  //    Stamping first is unrecoverable rather than merely early: `migrationApplies` is
328	  //    `want > have`, so the moment the stamp lands the record stops applying, stops
329	  //    vendoring, and the staged copy — the one remaining source of the content — is
330	  //    swept by the next cycle as a leftover. Holding the number back keeps the record
331	  //    in range, so an undelivered file is simply staged again next cycle, which is
332	  //    what makes a merged-but-undelivered PR self-healing instead of a silent loss.
333	  const packVersions = {};
334	  for (const p of plan) if (p.to !== null && !owesDelivery.has(p.id)) packVersions[p.id] = p.to;
335	  writeFileSync(settingsFile, `${JSON.stringify(withInstalledVersions(next, { packVersions }), null, 2)}\n`);
336	
337	  // 4. The same gate the engine flow uses, then the agentic tail's own question —
338	  //    ASKED OF THE RECORDS, NOT OF THE VERSION PLAN (#798).
339	  //
340	  //    This used to be `moved.length > 0`: any declared pack whose version number
341	  //    changed summoned a session. That is a fact about the CANON, and the stage
342	  //    exists for a fact about the MEMBER — the pack's new rules met content the
343	  //    canon has never seen. The two coincide only by accident.
344	  //
345	  //    The cost of conflating them was not theoretical. A record can only reach an
346	  //    up-to-date member if its pack's manifest version bumps (`migrationApplies` is
347	  //    `want > have` against the stamped number, and the stamp written is the
348	  //    manifest's). So every mechanical migration — a regex rewrite, a rename, a
349	  //    declaration seed, all deterministic and idempotent — had to buy a session on
350	  //    every member in the fleet to reach them at all. Deterministic work priced as
351	  //    agentic work is how a fleet learns to dread its own updates.
352	  //
353	  //    So the records answer. Each one's author knew which kind they were writing,
354	  //    and `applyStage` is where they say so. A bump carrying no such record is
355	  //    silent, which is what makes a first live run of an agentic change something
356	  //    you can aim at one member instead of fourteen at once.
357	  //
358	  //    THE SECOND ANSWERER IS THE DIFF (#1932), and it answers a different question:
359	  //    not "does this record need judgment" but "could this cycle's writes have
360	  //    broken the repo's own tests". A record's author cannot answer that one — the
361	  //    same mechanical rewrite is inert in one member and breaks a suite in the
362	  //    next — so it is read off what the cycle actually wrote (./converge-scope.mjs),
363	  //    and `runSelfTest` below is no substitute: it runs Claudinite's own probes,
364	  //    never the repo's suite. Asked at this point because every write of the cycle
365	  //    has landed in the working tree by now — the engine flow's, this flow's
366	  //    vendor, and every record's — and the terminal has yet to be decided.
367	  const testVisible = changesTestsCouldSee(targetRoot);
368	  const selftest = runSelfTest(targetRoot, selfTestRun);
369	  const decision = deliveryDecision({ selftestOk: selftest.ok, delivery, forceMergeOnRedCi });
370	  // A wiring failure rides out on `detail`, which the worker already prints and which
371	  // becomes the PR body and the work item's reason. Appended rather than given a
372	  // field of its own, because a new field only reaches a member when its worker
373	  // catches up a cycle later, and `detail` reaches every fielded worker today.
374	  // No flow computes a workflow any more, so there is no wiring failure left to ride
375	  // out on `detail`. The field stays null rather than absent: a fielded worker reads it,
376	  // and a key that vanished would read as a worker too old to report one.
377	  const wiringError = null;
378	  const detail = decision.why;
379	
380	  return outcome(decision.action === 'needs-human' ? NEEDS_HUMAN : 'ok', detail, {
381	    plan, files: packFiles.length, applied, selftest, decision, withheld,
382	    wiringError, testVisible, applyStage: applyStageFor(specs, withheld, testVisible),
383	  });
384	}
